<script setup>
import { ref, onMounted, computed } from 'vue';
import { request } from '../../api/http';
import { session } from '../../lib/session';
import { dateRange, downloadCsv } from '../../lib/cc';
const emit=defineEmits(['today']);const [today]=dateRange('today');
const from=ref(today),to=ref(today),data=ref(null),error=ref(''),busy=ref(false),search=ref('');
const rows=computed(()=>(data.value?.rows||[]).map(row=>({...row,employee_name:data.value.employees.find(e=>e.name===row.employee)?.employee_name||row.employee})).filter(row=>!search.value||`${row.employee_name} ${row.status}`.toLowerCase().includes(search.value.toLowerCase())));
async function load(){busy.value=true;error.value='';try{data.value=(await request('life_slimming.api.cc_attendance.snapshot',{args:{from_date:from.value,to_date:to.value},csrfToken:session.csrf_token})).message;if(from.value===today&&to.value===today){const employee=data.value.employees.find(e=>e.user_id===session.user);emit('today',data.value.rows.find(r=>r.employee===employee?.name)||{});}}catch(e){error.value=e.message;}finally{busy.value=false;}}
function exportRows(){downloadCsv('cc-attendance.csv',[{key:'employee_name',label:'Employee'},{key:'attendance_date',label:'Date'},{key:'status',label:'Status'},{key:'custom_check_in_time',label:'IN'},{key:'custom_check_out_time',label:'OUT'},{key:'working_hours',label:'Hours'}],rows.value);}
onMounted(load);
</script>
<template><section class="card"><header class="card-hdr">Staff Attendance <RouterLink :to="{name:'cc-roster'}">Open roster →</RouterLink></header><div class="card-body"><form class="cc-attendance-toolbar" @submit.prevent="load"><label>From <input v-model="from" type="date" required></label><label>To <input v-model="to" type="date" required></label><input v-model="search" type="search" placeholder="Search employee or status" aria-label="Search attendance"><button class="btn btn-g" :disabled="busy">{{busy?'Loading…':'Apply'}}</button><button type="button" class="btn btn-gy" :disabled="!rows.length" @click="exportRows">Export CSV</button></form><p v-if="error" role="alert" class="cc-error">{{error}}</p><div class="tbl-wrap"><table><thead><tr><th>Employee</th><th>Date</th><th>Status</th><th>IN</th><th>OUT</th><th>Hours</th></tr></thead><tbody><tr v-for="row in rows" :key="row.name"><td>{{row.employee_name}}</td><td>{{row.attendance_date}}</td><td>{{row.status}}</td><td>{{row.custom_check_in_time||'—'}}</td><td>{{row.custom_check_out_time||'—'}}</td><td>{{row.working_hours??'—'}}</td></tr><tr v-if="!busy&&!rows.length"><td colspan="6">No attendance records for this range.</td></tr></tbody></table></div></div></section></template>
<style scoped>.cc-attendance-toolbar{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin-bottom:15px}.cc-attendance-toolbar label{display:grid;gap:5px}.cc-attendance-toolbar input{padding:8px;border:1px solid #d8cfb8;border-radius:6px}</style>
